const trap = document.getElementById('modal');
const focusable = trap.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
const first = focusable[0];
const last = focusable[focusable.length - 1];

trap.addEventListener('keydown', (e) => {
  if (e.key === 'Tab') {
    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  }
});

slides.content:
When a modal closes, focus must return to the element that triggered it. This preserves context for the user.

```javascript
const trigger = document.getElementById('open-btn');
trigger.addEventListener('click', () => {
  // save trigger element
  lastFocused = document.activeElement;
  dialog.showModal();
});
dialog.addEventListener('close', () => {
  lastFocused.focus();
});
```

Never leave focus dangling at the top of the document.
